    /**
     * Method to retrieve the Obligation via ObligationFetchOneSummary
     * @param 	summary ObligationFetchOneSummary 
     * @return 	ObligationFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Obligation getObligation( ObligationFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ObligationFetchOneSummary arg cannot be null" );
    	
    	Obligation entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Obligation
        	// --------------------------------------
        	CompletableFuture<Obligation> futureEntity = queryGateway.query(new FindObligationQuery( new LoadObligationFilter( summary.getObligationId() ) ), ResponseTypes.instanceOf(Obligation.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Obligation with id " + summary.getObligationId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


